/// <summary>
/// MPJ_2864 - kscerri - 16/03/2021
/// Parameter to include number of tasks.
/// </summary>
/// <param name = "_numOfTasks">NumOfThreads</param>
/// <returns>NumOfThreads</returns>
[
    DataMemberAttribute, 
    SysOperationLabelAttribute('@MET:CustCreditLimitTasks'),
    SysOperationDisplayOrderAttribute('1')
]
public METNumOfTasks getNumOfTasks(METNumOfTasks _numOfTasks = numOfTasks)
{
    numOfTasks = _numOfTasks;
    return numOfTasks;
}

/// <summary>
/// 422033 - Customer credit limit optimisation
/// </summary>
/// <param name = "_fromCustomer">from customer account</param>
/// <returns>customer account RecId</returns>
[
    DataMemberAttribute,
    SysOperationControlVisibilityAttribute(false)
]
public RecId parmFromCustRecId(RecId _fromCustomer = fromCustomer)
{
    fromCustomer = _fromCustomer;
    return fromCustomer;
}

/// <summary>
/// 422033 - Customer credit limit optimisation
/// </summary>
/// <param name = "_toCustomer">to customer account</param>
/// <returns>customer account RecId</returns>
[
    DataMemberAttribute,
    SysOperationControlVisibilityAttribute(false)
]
public RecId parmToCustRecId(RecId _toCustomer = toCustomer)
{
    toCustomer = _toCustomer;
    return toCustomer;
}
